/// `LEBEDEV_ORDER[i] = (order, ngrid)` — port of `LebedevGrid.py:LEBEDEV_ORDER`
/// (the `{order → ngrid}` dict). Order 0 maps to a single-point degenerate
/// grid (used by `_default_ang` only via mapped orders ≥ 3).
#[rustfmt::skip]
pub const LEBEDEV_ORDER: &[(u32, u32)] = &[
    (0, 1), (3, 6), (5, 14), (7, 26), (9, 38), (11, 50), (13, 74), (15, 86),
    (17, 110), (19, 146), (21, 170), (23, 194), (25, 230), (27, 266), (29, 302),
    (31, 350), (35, 434), (41, 590), (47, 770), (53, 974), (59, 1202), (65, 1454),
    (71, 1730), (77, 2030), (83, 2354), (89, 2702), (95, 3074), (101, 3470),
    (107, 3890), (113, 4334), (119, 4802), (125, 5294), (131, 5810),
];

/// Map a Lebedev *order* to its point count (`LEBEDEV_ORDER[order]` lookup).
/// Returns `None` for unsupported orders.
#[must_use]
pub fn lebedev_order(order: u32) -> Option<u32> {
    LEBEDEV_ORDER
        .iter()
        .find(|&&(o, _)| o == order)
        .map(|&(_, n)| n)
}

/// The set of supported Lebedev point counts — `LEBEDEV_NGRID` upstream.
/// (Equals the second element of each `LEBEDEV_ORDER` pair.)
#[must_use]
pub fn lebedev_ngrid() -> Vec<u32> {
    LEBEDEV_ORDER.iter().map(|&(_, n)| n).collect()
}

/// Expand a single octahedral-symmetry seed `(code, a, b, v)` into its Oh
/// point set. Port of `SphGenOh`. Returns a flat `Vec` of `(x, y, z, w)`
/// rows (length = the code's point count). Codes 0/1/2 derive `a` internally
/// (ignoring the passed `a`); codes 3/4/5 derive `b`/`c` from the input `a`
/// (and `b` for code 5).
#[must_use]
pub fn sph_gen_oh(code: u8, a_in: f64, b_in: f64, v: f64) -> Vec<[f64; 4]> {
    match code {
        0 => {
            let a = 1.0_f64;
            vec![
                [a, 0., 0., v],
                [-a, 0., 0., v],
                [0., a, 0., v],
                [0., -a, 0., v],
                [0., 0., a, v],
                [0., 0., -a, v],
            ]
        }
        1 => {
            let a = 0.5_f64.sqrt();
            vec![
                [0., a, a, v],
                [0., -a, a, v],
                [0., a, -a, v],
                [0., -a, -a, v],
                [a, 0., a, v],
                [-a, 0., a, v],
                [a, 0., -a, v],
                [-a, 0., -a, v],
                [a, a, 0., v],
                [-a, a, 0., v],
                [a, -a, 0., v],
                [-a, -a, 0., v],
            ]
        }
        2 => {
            let a = (1.0_f64 / 3.0).sqrt();
            vec![
                [a, a, a, v],
                [-a, a, a, v],
                [a, -a, a, v],
                [-a, -a, a, v],
                [a, a, -a, v],
                [-a, a, -a, v],
                [a, -a, -a, v],
                [-a, -a, -a, v],
            ]
        }
        3 => {
            let a = a_in;
            let b = (1.0 - 2.0 * a * a).sqrt();
            vec![
                [a, a, b, v],
                [-a, a, b, v],
                [a, -a, b, v],
                [-a, -a, b, v],
                [a, a, -b, v],
                [-a, a, -b, v],
                [a, -a, -b, v],
                [-a, -a, -b, v],
                [a, b, a, v],
                [-a, b, a, v],
                [a, -b, a, v],
                [-a, -b, a, v],
                [a, b, -a, v],
                [-a, b, -a, v],
                [a, -b, -a, v],
                [-a, -b, -a, v],
                [b, a, a, v],
                [-b, a, a, v],
                [b, -a, a, v],
                [-b, -a, a, v],
                [b, a, -a, v],
                [-b, a, -a, v],
                [b, -a, -a, v],
                [-b, -a, -a, v],
            ]
        }
        4 => {
            let a = a_in;
            let b = (1.0 - a * a).sqrt();
            vec![
                [a, b, 0., v],
                [-a, b, 0., v],
                [a, -b, 0., v],
                [-a, -b, 0., v],
                [b, a, 0., v],
                [-b, a, 0., v],
                [b, -a, 0., v],
                [-b, -a, 0., v],
                [a, 0., b, v],
                [-a, 0., b, v],
                [a, 0., -b, v],
                [-a, 0., -b, v],
                [b, 0., a, v],
                [-b, 0., a, v],
                [b, 0., -a, v],
                [-b, 0., -a, v],
                [0., a, b, v],
                [0., -a, b, v],
                [0., a, -b, v],
                [0., -a, -b, v],
                [0., b, a, v],
                [0., -b, a, v],
                [0., b, -a, v],
                [0., -b, -a, v],
            ]
        }
        5 => {
            let a = a_in;
            let b = b_in;
            let c = (1.0 - a * a - b * b).sqrt();
            vec![
                [a, b, c, v],
                [-a, b, c, v],
                [a, -b, c, v],
                [-a, -b, c, v],
                [a, b, -c, v],
                [-a, b, -c, v],
                [a, -b, -c, v],
                [-a, -b, -c, v],
                [a, c, b, v],
                [-a, c, b, v],
                [a, -c, b, v],
                [-a, -c, b, v],
                [a, c, -b, v],
                [-a, c, -b, v],
                [a, -c, -b, v],
                [-a, -c, -b, v],
                [b, a, c, v],
                [-b, a, c, v],
                [b, -a, c, v],
                [-b, -a, c, v],
                [b, a, -c, v],
                [-b, a, -c, v],
                [b, -a, -c, v],
                [-b, -a, -c, v],
                [b, c, a, v],
                [-b, c, a, v],
                [b, -c, a, v],
                [-b, -c, a, v],
                [b, c, -a, v],
                [-b, c, -a, v],
                [b, -c, -a, v],
                [-b, -c, -a, v],
                [c, a, b, v],
                [-c, a, b, v],
                [c, -a, b, v],
                [-c, -a, b, v],
                [c, a, -b, v],
                [-c, a, -b, v],
                [c, -a, -b, v],
                [-c, -a, -b, v],
                [c, b, a, v],
                [-c, b, a, v],
                [c, -b, a, v],
                [-c, -b, a, v],
                [c, b, -a, v],
                [-c, b, -a, v],
                [c, -b, -a, v],
                [-c, -b, -a, v],
            ]
        }
        _ => Vec::new(),
    }
}

/// Build the full angular grid for a given Lebedev point count `points`.
/// Port of `MakeAngularGrid` / `MakeAngularGrid_<N>`: vstack the expansion of
/// every seed for that order, in seed order. Returns `(x, y, z, w)` rows.
///
/// `points ∈ {0, 1}` returns the single degenerate point `(0,0,0,1)` (matches
/// `MakeAngularGrid` upstream). Unsupported counts return `None`.
#[must_use]
pub fn make_angular_grid(points: u32) -> Option<Vec<[f64; 4]>> {
    if points == 0 || points == 1 {
        return Some(vec![[0.0, 0.0, 0.0, 1.0]]);
    }
    let seeds = LEBEDEV_SEEDS.iter().find(|&&(n, _)| n == points)?.1;
    let mut out = Vec::with_capacity(points as usize);
    for &(code, a, b, v) in seeds {
        out.extend(sph_gen_oh(code, a, b, v));
    }
    Some(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sph_gen_oh_point_counts_per_code() {
        // code → count: 0→6, 1→12, 2→8, 3→24, 4→24, 5→48.
        assert_eq!(sph_gen_oh(0, 0., 0., 1.).len(), 6);
        assert_eq!(sph_gen_oh(1, 0., 0., 1.).len(), 12);
        assert_eq!(sph_gen_oh(2, 0., 0., 1.).len(), 8);
        assert_eq!(sph_gen_oh(3, 0.3, 0., 1.).len(), 24);
        assert_eq!(sph_gen_oh(4, 0.4, 0., 1.).len(), 24);
        assert_eq!(sph_gen_oh(5, 0.4, 0.5, 1.).len(), 48);
    }

    #[test]
    fn sph_gen_oh_code0_coords() {
        // code 0 = the 6 axis points (±1 on each axis) with weight v.
        let g = sph_gen_oh(0, 0., 0., 0.5);
        assert_eq!(g[0], [1.0, 0.0, 0.0, 0.5]);
        assert_eq!(g[1], [-1.0, 0.0, 0.0, 0.5]);
        assert_eq!(g[4], [0.0, 0.0, 1.0, 0.5]);
        assert_eq!(g[5], [0.0, 0.0, -1.0, 0.5]);
    }

    #[test]
    fn sph_gen_oh_code2_is_unit_sphere() {
        // code 2 points all lie on the unit sphere (a = 1/sqrt(3)).
        for p in sph_gen_oh(2, 0., 0., 1.) {
            let r2 = p[0] * p[0] + p[1] * p[1] + p[2] * p[2];
            assert!((r2 - 1.0).abs() < 1e-15);
        }
    }

    #[test]
    fn make_angular_grid_n_matches_order_counts() {
        // Every seeded order expands to exactly N points.
        for &(n, _) in LEBEDEV_SEEDS {
            let g = make_angular_grid(n).expect("seeded order builds");
            assert_eq!(g.len() as u32, n, "MakeAngularGrid_{n} count mismatch");
        }
    }

    #[test]
    fn make_angular_grid_points_on_unit_sphere() {
        // Spot-check a few orders: all points lie on the unit sphere.
        for &n in &[6u32, 50, 110, 302, 434] {
            let g = make_angular_grid(n).expect("order builds");
            for p in g {
                let r2 = p[0] * p[0] + p[1] * p[1] + p[2] * p[2];
                assert!((r2 - 1.0).abs() < 1e-12, "order {n} point off-sphere");
            }
        }
    }

    #[test]
    fn make_angular_grid_weights_sum_to_one() {
        // Lebedev weights are normalised to sum to 1.0 (header note line 20).
        for &n in &[6u32, 14, 50, 86, 302, 590] {
            let g = make_angular_grid(n).expect("order builds");
            let s: f64 = g.iter().map(|p| p[3]).sum();
            assert!((s - 1.0).abs() < 1e-10, "order {n} weights sum = {s}");
        }
    }

    #[test]
    fn lebedev_order_map_matches_upstream() {
        // Spot-check the order→ngrid mapping used by _default_ang.
        assert_eq!(lebedev_order(3), Some(6));
        assert_eq!(lebedev_order(11), Some(50));
        assert_eq!(lebedev_order(29), Some(302));
        assert_eq!(lebedev_order(35), Some(434));
        assert_eq!(lebedev_order(65), Some(1454));
        assert_eq!(lebedev_order(131), Some(5810));
        assert_eq!(lebedev_order(4), None); // not an even-listed order
    }

    #[test]
    fn lebedev_order_has_33_entries() {
        // Upstream LEBEDEV_ORDER has 33 entries (order 0 + 32 real grids).
        assert_eq!(LEBEDEV_ORDER.len(), 33);
        // LEBEDEV_SEEDS covers the 32 buildable orders (excludes the order-0
        // degenerate single point).
        assert_eq!(LEBEDEV_SEEDS.len(), 32);
    }

    #[test]
    fn degenerate_single_point_grid() {
        assert_eq!(make_angular_grid(0), Some(vec![[0.0, 0.0, 0.0, 1.0]]));
        assert_eq!(make_angular_grid(1), Some(vec![[0.0, 0.0, 0.0, 1.0]]));
    }
}
